import{_ as a,o as t,c as o,a5 as d}from"./chunks/framework.B-qY3dMa.js";const l="/docs/images/connect/claude-desktop-01.jpg",r="/docs/images/connect/claude-desktop-02.png",c="/docs/images/connect/claude-desktop-03.png",i="/docs/images/connect/claude-desktop-04.jpg",s="/docs/images/connect/claude-desktop-05.jpg",q=JSON.parse('{"title":"Claude 桌面版接入熊猫算力 · 完整教程","description":"","frontmatter":{"title":"Claude 桌面版接入熊猫算力 · 完整教程","date":"2026-05-19T00:00:00.000Z","category":"拓展连接","tags":["Claude Desktop","桌面版","接入教程","开发者"]},"headers":[],"relativePath":"connect/claude-desktop.md","filePath":"connect/claude-desktop.md","lastUpdated":1779265215000}'),p={name:"connect/claude-desktop.md"};function n(h,e,u,b,k,_){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="claude-桌面版接入熊猫算力-·-完整教程" tabindex="-1">Claude 桌面版接入熊猫算力 · 完整教程 <a class="header-anchor" href="#claude-桌面版接入熊猫算力-·-完整教程" aria-label="Permalink to &quot;Claude 桌面版接入熊猫算力 · 完整教程&quot;">​</a></h1><p>Claude Desktop 可以通过官方提供的第三方推理入口，把请求转发到你自己的 API 网关。接入熊猫算力后，不需要海外手机号，也不需要订阅 Pro，就能直接用国内中转。</p><p><strong>预计用时：5 分钟 · 推荐人群：开发者 · 支持平台：Windows / macOS</strong></p><hr><h2 id="什么是-claude-desktop-接入" tabindex="-1">什么是 Claude Desktop 接入？ <a class="header-anchor" href="#什么是-claude-desktop-接入" aria-label="Permalink to &quot;什么是 Claude Desktop 接入？&quot;">​</a></h2><p>Claude Desktop 的开发者模式里有一个第三方推理配置入口，填写 Base URL 和 API Key 后，就能把请求交给熊猫算力的 Anthropic 兼容网关。</p><div class="tip custom-block"><p class="custom-block-title">提前说明</p><p>这条路走的是官方允许的第三方推理入口，不是改客户端核心逻辑。</p></div><hr><h2 id="step-01-下载安装-claude-desktop" tabindex="-1">Step 01：下载安装 Claude Desktop <a class="header-anchor" href="#step-01-下载安装-claude-desktop" aria-label="Permalink to &quot;Step 01：下载安装 Claude Desktop&quot;">​</a></h2><h3 id="_1-下载客户端" tabindex="-1">1. 下载客户端 <a class="header-anchor" href="#_1-下载客户端" aria-label="Permalink to &quot;1. 下载客户端&quot;">​</a></h3><p>前往 Claude 官方下载页，下载对应系统的安装包。Windows 一般是 <code>Claude Setup.exe</code>。</p><p><img src="'+l+'" alt="Claude Setup.exe 下载弹窗"></p><h3 id="_2-安装后先停在登录页" tabindex="-1">2. 安装后先停在登录页 <a class="header-anchor" href="#_2-安装后先停在登录页" aria-label="Permalink to &quot;2. 安装后先停在登录页&quot;">​</a></h3><p>安装完成后先打开客户端，但不要完成账号登录。停在登录页即可。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>如果你已经完整登录到主界面，后面的开发者入口可能被锁住，需要先退出并重启客户端。</p></div><hr><h2 id="step-02-开启开发者模式" tabindex="-1">Step 02：开启开发者模式 <a class="header-anchor" href="#step-02-开启开发者模式" aria-label="Permalink to &quot;Step 02：开启开发者模式&quot;">​</a></h2><h3 id="_1-打开菜单" tabindex="-1">1. 打开菜单 <a class="header-anchor" href="#_1-打开菜单" aria-label="Permalink to &quot;1. 打开菜单&quot;">​</a></h3><p>在登录页状态下，点击 <code>Help → Troubleshooting → Enable Developer Mode</code>。</p><p><img src="'+r+'" alt="Help → Troubleshooting → Enable Developer Mode 菜单路径"></p><h3 id="_2-确认菜单出现" tabindex="-1">2. 确认菜单出现 <a class="header-anchor" href="#_2-确认菜单出现" aria-label="Permalink to &quot;2. 确认菜单出现&quot;">​</a></h3><p>启用成功后，顶部菜单会多出一个 <code>Developer</code> 选项。</p><div class="tip custom-block"><p class="custom-block-title">如果没看到</p><p>先把 Claude 完全退出，再重新打开一次，很多时候是进程没有真正关掉。</p></div><hr><h2 id="step-03-打开第三方推理配置" tabindex="-1">Step 03：打开第三方推理配置 <a class="header-anchor" href="#step-03-打开第三方推理配置" aria-label="Permalink to &quot;Step 03：打开第三方推理配置&quot;">​</a></h2><h3 id="_1-进入配置面板" tabindex="-1">1. 进入配置面板 <a class="header-anchor" href="#_1-进入配置面板" aria-label="Permalink to &quot;1. 进入配置面板&quot;">​</a></h3><p>点击 <code>Developer</code>，选择 <code>Configure Third-Party Inference...</code>。</p><p><img src="'+c+'" alt="Developer 菜单展开,高亮 Configure Third-Party Inference"></p><h3 id="_2-选择网关类型" tabindex="-1">2. 选择网关类型 <a class="header-anchor" href="#_2-选择网关类型" aria-label="Permalink to &quot;2. 选择网关类型&quot;">​</a></h3><p>在面板里选择 <code>Connection</code>，然后把网关类型设成 <code>Gateway (Anthropic-compatible)</code>。</p><hr><h2 id="step-04-填写网关信息" tabindex="-1">Step 04：填写网关信息 <a class="header-anchor" href="#step-04-填写网关信息" aria-label="Permalink to &quot;Step 04：填写网关信息&quot;">​</a></h2><h3 id="_1-写入-base-url-和-key" tabindex="-1">1. 写入 Base URL 和 Key <a class="header-anchor" href="#_1-写入-base-url-和-key" aria-label="Permalink to &quot;1. 写入 Base URL 和 Key&quot;">​</a></h3><p>把熊猫算力的接入信息填进去：</p><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>Gateway base URL</td><td><code>https://b.pandatoken.net</code></td></tr><tr><td>Gateway API key</td><td>你的熊猫算力 <code>sk-</code> 令牌</td></tr><tr><td>Gateway auth scheme</td><td><code>bearer</code></td></tr><tr><td>Gateway extra headers</td><td>留空</td></tr></tbody></table><p><img src="'+i+'" alt="Configure third-party inference 主面板,填写 Gateway base URL 和 API Key"></p><h3 id="_2-本地应用配置" tabindex="-1">2. 本地应用配置 <a class="header-anchor" href="#_2-本地应用配置" aria-label="Permalink to &quot;2. 本地应用配置&quot;">​</a></h3><p>点击右下角的 <code>Apply locally</code>，不要点 <code>Export</code>。然后完全退出 Claude Desktop 再重新打开。</p><div class="tip custom-block"><p class="custom-block-title">Apply locally vs Export</p><p><code>Apply locally</code> 是写入本机客户端配置，<code>Export</code> 是导出给别人用的配置文件，这一步不需要点 <code>Export</code>。</p></div><hr><h2 id="step-05-验证连通" tabindex="-1">Step 05：验证连通 <a class="header-anchor" href="#step-05-验证连通" aria-label="Permalink to &quot;Step 05：验证连通&quot;">​</a></h2><h3 id="_1-重新启动客户端" tabindex="-1">1. 重新启动客户端 <a class="header-anchor" href="#_1-重新启动客户端" aria-label="Permalink to &quot;1. 重新启动客户端&quot;">​</a></h3><p>重启后，登录页会出现 <code>Continue with local gateway</code> 选项，点它进入主界面。</p><h3 id="_2-发一句测试消息" tabindex="-1">2. 发一句测试消息 <a class="header-anchor" href="#_2-发一句测试消息" aria-label="Permalink to &quot;2. 发一句测试消息&quot;">​</a></h3><p>随便发一句“你好”，能正常返回回复就说明接入成功。</p><p><img src="'+s+'" alt="Cowork 主界面成功对话,左下角 Cowork 3P · Gateway,右下角模型选择器展开"></p><h3 id="_3-成功标志" tabindex="-1">3. 成功标志 <a class="header-anchor" href="#_3-成功标志" aria-label="Permalink to &quot;3. 成功标志&quot;">​</a></h3><ol><li>左下角显示 <code>Cowork 3P · Gateway</code></li><li>右下角可以切换模型</li><li><code>Cowork</code> 和 <code>Code</code> 两种模式都可用</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="_1-看不到-developer-菜单" tabindex="-1">1. 看不到 Developer 菜单 <a class="header-anchor" href="#_1-看不到-developer-菜单" aria-label="Permalink to &quot;1. 看不到 Developer 菜单&quot;">​</a></h3><p>先确认 Claude 是否完全退出，再重新打开。如果还不行，检查版本是否过旧。</p><h3 id="_2-点了-apply-locally-没反应" tabindex="-1">2. 点了 Apply locally 没反应 <a class="header-anchor" href="#_2-点了-apply-locally-没反应" aria-label="Permalink to &quot;2. 点了 Apply locally 没反应&quot;">​</a></h3><p>大概率是客户端没有真正重启，先退出干净再开一次。</p><h3 id="_3-401-unauthorized-invalid-api-key" tabindex="-1">3. 401 Unauthorized / Invalid API key <a class="header-anchor" href="#_3-401-unauthorized-invalid-api-key" aria-label="Permalink to &quot;3. 401 Unauthorized / Invalid API key&quot;">​</a></h3><p>检查 API Key 是否复制完整，前后有没有空格，是否还是熊猫算力后台生成的 <code>sk-</code> 令牌。</p><h3 id="_4-connection-refused-econnrefused" tabindex="-1">4. Connection refused / ECONNREFUSED <a class="header-anchor" href="#_4-connection-refused-econnrefused" aria-label="Permalink to &quot;4. Connection refused / ECONNREFUSED&quot;">​</a></h3><p>确认 Base URL 是 <code>https://b.pandatoken.net</code>，不要多写 <code>/</code>，也不要写成 <code>http</code>。</p><h3 id="_5-请求超时" tabindex="-1">5. 请求超时 <a class="header-anchor" href="#_5-请求超时" aria-label="Permalink to &quot;5. 请求超时&quot;">​</a></h3><p>本地代理软件可能在干扰桌面端请求，建议暂时关闭代理，或者把中转站域名加入直连白名单。</p><h3 id="_6-不小心登录了官方账号" tabindex="-1">6. 不小心登录了官方账号 <a class="header-anchor" href="#_6-不小心登录了官方账号" aria-label="Permalink to &quot;6. 不小心登录了官方账号&quot;">​</a></h3><p>先退出账号，再完全关闭客户端重开。必要时可以清理用户配置目录后重新配置。</p><hr><p>接入完成后，Claude Desktop 就会通过熊猫算力网关工作，后续模型和额度都在熊猫算力后台统一查看。</p>',64)])])}const f=a(p,[["render",n]]);export{q as __pageData,f as default};
